/**
 * PageQueueItem.tsx — Satu item di antrean halaman
 */

import React from "react";
import {
  Button,
  Text,
  Tooltip,
} from "@fluentui/react-components";
import {
  ArrowUp24Regular,
  ArrowDown24Regular,
  Copy24Regular,
  Delete24Regular,
  Warning16Filled,
} from "@fluentui/react-icons";
import type { PageItem } from "@shared/types";
import { formatSheetRange } from "@shared/utils";

interface Props {
  page: PageItem;
  index: number;
  isSelected: boolean;
  isFirst: boolean;
  isLast: boolean;
  disabled: boolean;
  onSelect: () => void;
  onMoveUp: () => void;
  onMoveDown: () => void;
  onDuplicate: () => void;
  onRemove: () => void;
}

export const PageQueueItem: React.FC<Props> = ({
  page,
  index,
  isSelected,
  isFirst,
  isLast,
  disabled,
  onSelect,
  onMoveUp,
  onMoveDown,
  onDuplicate,
  onRemove,
}) => {
  const label = formatSheetRange(page.sheetName, page.address);

  return (
    <div
      className={`queue-item ${isSelected ? "queue-item--selected" : ""} ${!page.isValid ? "queue-item--invalid" : ""}`}
      role="option"
      aria-selected={isSelected}
      aria-label={`${index + 1}. ${label}`}
      onClick={onSelect}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect();
        }
      }}
      tabIndex={0}
    >
      {/* Nomor urut */}
      <span className="queue-item__number">{index + 1}</span>

      {/* Label range */}
      <span className="queue-item__label">
        <Text size={200} truncate wrap={false}>
          {label}
        </Text>
        {!page.isValid && (
          <Tooltip content={page.validationError ?? "Range tidak valid"} relationship="label">
            <Warning16Filled className="queue-item__warning" />
          </Tooltip>
        )}
      </span>

      {/* Tombol aksi */}
      <span className="queue-item__actions">
        <Tooltip content="Naik" relationship="label">
          <Button
            appearance="subtle"
            icon={<ArrowUp24Regular />}
            size="small"
            disabled={isFirst || disabled}
            onClick={(e) => { e.stopPropagation(); onMoveUp(); }}
            aria-label="Naik"
          />
        </Tooltip>
        <Tooltip content="Turun" relationship="label">
          <Button
            appearance="subtle"
            icon={<ArrowDown24Regular />}
            size="small"
            disabled={isLast || disabled}
            onClick={(e) => { e.stopPropagation(); onMoveDown(); }}
            aria-label="Turun"
          />
        </Tooltip>
        <Tooltip content="Duplikat" relationship="label">
          <Button
            appearance="subtle"
            icon={<Copy24Regular />}
            size="small"
            disabled={disabled}
            onClick={(e) => { e.stopPropagation(); onDuplicate(); }}
            aria-label="Duplikat"
          />
        </Tooltip>
        <Tooltip content="Hapus" relationship="label">
          <Button
            appearance="subtle"
            icon={<Delete24Regular />}
            size="small"
            disabled={disabled}
            onClick={(e) => { e.stopPropagation(); onRemove(); }}
            aria-label="Hapus"
          />
        </Tooltip>
      </span>
    </div>
  );
};
