/**
 * App.tsx — Komponen utama task pane Excel Print Studio
 *
 * Layout (PRD §5):
 * ┌──────────────────────────┐
 * │ Header + Tombol Tambah   │
 * │ Antrean Halaman          │
 * │ Tab Layout Settings      │
 * │ Pratinjau Cepat          │
 * │ Action Bar (Ekspor/Cetak)│
 * └──────────────────────────┘
 */

import React, { useEffect, useReducer } from "react";
import {
  Text,
  Divider,
  MessageBar,
  MessageBarBody,
} from "@fluentui/react-components";
import { AppContext, appReducer, initialState } from "@store/appState";
import { loadQueue } from "@services/persistenceService";
import { findLeftoverStagingSheets, deleteStagingSheets } from "@services/excelService";
import { loadLocalePreference } from "@shared/i18n";
import { getTranslations } from "@shared/i18n";
import { PageQueue } from "./components/PageQueue/PageQueue";
import { LayoutTabs } from "./components/LayoutSettings/LayoutTabs";
import { QuickPreview } from "./components/Preview/QuickPreview";
import { ActionBar } from "./components/ActionBar/ActionBar";
import { LogViewerButton } from "./components/LogViewer/LogViewerDialog";
import "./App.css";

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    ...initialState,
    locale: loadLocalePreference(),
  });

  const t = getTranslations(state.locale);

  // ─── Inisialisasi: muat antrean & cek staging sisa ──────────
  useEffect(() => {
    async function init() {
      // Muat antrean tersimpan dari workbook
      try {
        const savedPages = await loadQueue();
        if (savedPages.length > 0) {
          dispatch({ type: "SET_PAGES", pages: savedPages });
        }
      } catch {
        console.warn("Gagal memuat antrean tersimpan.");
      }

      // Deteksi staging sisa dari sesi crash (PRD §9)
      try {
        const leftover = await findLeftoverStagingSheets();
        if (leftover.length > 0) {
          dispatch({
            type: "SET_STATUS",
            message: {
              type: "warning",
              text: `${t.cleanupFound} (${leftover.length} sheet)`,
            },
          });
          // Auto-cleanup
          await deleteStagingSheets(leftover);
          dispatch({
            type: "SET_STATUS",
            message: { type: "success", text: t.cleanupDone },
          });
        }
      } catch {
        // Non-blocking
      }
    }

    init();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <AppContext.Provider value={{ state, dispatch }}>
      <div className="app-container">
        {/* Header */}
        <header className="app-header">
          <Text as="h1" size={500} weight="semibold">
            {t.appTitle}
          </Text>
          <LogViewerButton />
        </header>

        <Divider />

        {/* Antrean Halaman */}
        <section className="app-section">
          <PageQueue />
        </section>

        <Divider />

        {/* Tab Layout Settings */}
        {state.selectedPageIndex !== null && (
          <section className="app-section">
            <LayoutTabs />
          </section>
        )}

        <Divider />

        {/* Pratinjau Cepat */}
        <section className="app-section">
          <QuickPreview />
        </section>

        <Divider />

        {/* Status message */}
        {state.statusMessage && (
          <div className="app-status">
            <MessageBar
              intent={
                state.statusMessage.type === "error"
                  ? "error"
                  : state.statusMessage.type === "warning"
                    ? "warning"
                    : state.statusMessage.type === "success"
                      ? "success"
                      : "info"
              }
            >
              <MessageBarBody>{state.statusMessage.text}</MessageBarBody>
            </MessageBar>
          </div>
        )}

        {/* Action Bar */}
        <footer className="app-footer">
          <ActionBar />
        </footer>
      </div>
    </AppContext.Provider>
  );
};

export default App;
