/**
 * ScaleTab.tsx — Tab pengaturan skala
 * Ref: PRD §4 Fitur 2E
 */

import React from "react";
import {
  RadioGroup,
  Radio,
  Slider,
  SpinButton,
  Text,
} from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { SCALE_SLIDER_MIN, SCALE_SLIDER_MAX, SCALE_MIN, SCALE_MAX, SCALE_WARNING_THRESHOLD } from "@shared/constants";
import type { ScaleMode } from "@shared/types";

export const ScaleTab: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage, selectedPageIndex, updatePage } = usePageQueue();

  if (!selectedPage || selectedPageIndex === null) return null;

  const handleModeChange = (_: unknown, data: { value: string }) => {
    updatePage(selectedPageIndex, { scaleMode: data.value as ScaleMode });
  };

  const handleCustomScaleSlider = (_: unknown, data: { value: number }) => {
    updatePage(selectedPageIndex, { customScale: data.value });
  };

  const handleCustomScaleSpin = (_: unknown, data: { value?: number | null }) => {
    if (data.value != null) {
      const clamped = Math.min(SCALE_MAX, Math.max(SCALE_MIN, data.value));
      updatePage(selectedPageIndex, { customScale: clamped });
    }
  };

  return (
    <div className="scale-tab">
      {/* Mode skala */}
      <RadioGroup
        value={selectedPage.scaleMode}
        onChange={handleModeChange}
      >
        <Radio value="fitWidth" label={t.fitWidth} />
        <Radio value="fitPage" label={t.fitPage} />
        <Radio value="custom" label={t.customScale} />
        <Radio value="actual" label={t.actualSize} />
      </RadioGroup>

      {/* Slider + input kustom */}
      {selectedPage.scaleMode === "custom" && (
        <div style={{ marginTop: 8 }}>
          <div className="form-row">
            <Slider
              min={SCALE_SLIDER_MIN}
              max={SCALE_SLIDER_MAX}
              value={selectedPage.customScale}
              onChange={handleCustomScaleSlider}
              step={5}
              style={{ flex: 1 }}
            />
            <SpinButton
              size="small"
              value={selectedPage.customScale}
              min={SCALE_MIN}
              max={SCALE_MAX}
              step={5}
              onChange={handleCustomScaleSpin}
              style={{ width: 70 }}
            />
            <Text size={200}>%</Text>
          </div>

          {/* Peringatan skala kecil */}
          {selectedPage.customScale < SCALE_WARNING_THRESHOLD && (
            <Text
              size={100}
              style={{ color: "var(--colorPaletteYellowForeground1)" }}
            >
              {t.scaleWarning}
            </Text>
          )}
        </div>
      )}
    </div>
  );
};
