/**
 * PositionGrid.tsx — Grid posisi 9 titik (3×3)
 *
 * Inspirasi: FastStone Image Viewer print dialog.
 * Ref: PRD §4 Fitur 2C, §5
 */

import React from "react";
import { Text, Tooltip } from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import type { HorizontalPosition, VerticalPosition } from "@shared/types";
import "./PositionGrid.css";

const HORIZONTAL: HorizontalPosition[] = ["left", "center", "right"];
const VERTICAL: VerticalPosition[] = ["top", "center", "bottom"];

export const PositionGrid: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage, selectedPageIndex, updatePage } = usePageQueue();

  if (!selectedPage || selectedPageIndex === null) return null;

  const hLabels: Record<HorizontalPosition, string> = {
    left: t.posLeft,
    center: t.posCenter,
    right: t.posRight,
  };

  const vLabels: Record<VerticalPosition, string> = {
    top: t.posTop,
    center: t.posMiddle,
    bottom: t.posBottom,
  };

  const handleClick = (h: HorizontalPosition, v: VerticalPosition) => {
    updatePage(selectedPageIndex, {
      position: { horizontal: h, vertical: v },
    });
  };

  const handleKeyDown = (e: React.KeyboardEvent, h: HorizontalPosition, v: VerticalPosition) => {
    const hIdx = HORIZONTAL.indexOf(h);
    const vIdx = VERTICAL.indexOf(v);

    let nextH = h;
    let nextV = v;

    switch (e.key) {
      case "ArrowRight":
        nextH = HORIZONTAL[(hIdx + 1) % HORIZONTAL.length];
        e.preventDefault();
        break;
      case "ArrowLeft":
        nextH = HORIZONTAL[(hIdx - 1 + HORIZONTAL.length) % HORIZONTAL.length];
        e.preventDefault();
        break;
      case "ArrowDown":
        nextV = VERTICAL[(vIdx + 1) % VERTICAL.length];
        e.preventDefault();
        break;
      case "ArrowUp":
        nextV = VERTICAL[(vIdx - 1 + VERTICAL.length) % VERTICAL.length];
        e.preventDefault();
        break;
      default:
        return;
    }

    handleClick(nextH, nextV);
  };

  return (
    <div className="position-grid-container">
      <Text size={200} weight="semibold">{t.positionLabel}</Text>

      <div className="position-grid" role="radiogroup" aria-label={t.positionLabel}>
        {VERTICAL.map((v) =>
          HORIZONTAL.map((h) => {
            const isSelected =
              selectedPage.position.horizontal === h &&
              selectedPage.position.vertical === v;

            const label = `${vLabels[v]}-${hLabels[h]}`;

            return (
              <Tooltip content={label} relationship="label" key={`${v}-${h}`}>
                <button
                  className={`position-cell ${isSelected ? "position-cell--selected" : ""}`}
                  role="radio"
                  aria-checked={isSelected}
                  aria-label={label}
                  onClick={() => handleClick(h, v)}
                  onKeyDown={(e) => handleKeyDown(e, h, v)}
                  tabIndex={isSelected ? 0 : -1}
                >
                  <span className="position-dot" />
                </button>
              </Tooltip>
            );
          })
        )}
      </div>

      <Text size={100} className="form-note">{t.positionNote}</Text>
    </div>
  );
};
