/**
 * stagingService.ts — Pengelolaan sheet staging
 *
 * Membuat salinan sheet per halaman antrean, mengatur pageLayout,
 * dan membersihkan setelah selesai.
 * Ref: PRD §4.1 (staging), §4.4 (pemulihan state)
 */

import type { PageItem, LayoutCalculation } from "@shared/types";
import { PAPER_SIZES } from "@shared/paperSizes";
import { makeStagingName } from "@shared/utils";
import { logger } from "./loggerService";

/**
 * Buat satu sheet staging dari satu halaman antrean.
 *
 * Langkah:
 * 1. Salin sheet sumber (worksheet.copy) — mempertahankan grafik, gambar, format.
 * 2. Atur nama staging (prefix __PS_).
 * 3. Atur area cetak (setPrintArea) ke range yang dipilih.
 * 4. Terapkan semua pengaturan pageLayout.
 * 5. Sembunyikan sheet staging.
 *
 * @param page - Data halaman dari antrean
 * @param index - Indeks dalam antrean (untuk penamaan)
 * @param layout - Hasil kalkulasi layout (dari layoutEngine)
 */
export async function createStagingSheet(
  page: PageItem,
  index: number,
  layout: LayoutCalculation
): Promise<string> {
  const stagingName = makeStagingName(index);

  try {
    await Excel.run(async (context) => {
      // 1. Ambil sheet sumber berdasarkan sheetId
      const sheets = context.workbook.worksheets;
      sheets.load("items/id, items/name");
      await context.sync();

      const sourceSheet = sheets.items.find((s) => s.id === page.sheetId);
      if (!sourceSheet) {
        throw new Error(`Sheet sumber "${page.sheetName}" tidak ditemukan.`);
      }

      // 2. Salin sheet sumber
      const copiedSheet = sourceSheet.copy("End");
      copiedSheet.load("name");
      await context.sync();

      // 3. Ganti nama ke staging name
      copiedSheet.name = stagingName;
      await context.sync();

      // 4. Atur area cetak
      const printRange = copiedSheet.getRange(page.address);
      copiedSheet.pageLayout.setPrintArea(printRange);

      // 5. Terapkan pengaturan pageLayout
      const paperSize = PAPER_SIZES[page.paper];
      if (paperSize) {
        copiedSheet.pageLayout.paperSize = paperSize.excelPaperType as any;
      }

      // Orientasi
      const isLandscape = page.orientation === "landscape" ||
        (page.autoRotate && layout.scaledContentWidth > layout.scaledContentHeight);
      copiedSheet.pageLayout.orientation = isLandscape
        ? Excel.PageOrientation.landscape
        : Excel.PageOrientation.portrait;

      // Margin (dari kalkulasi 9-titik, sudah dalam poin)
      copiedSheet.pageLayout.setPrintMargins(
        Excel.PrintMarginUnit.points,
        {
          top: layout.computedMargins.top,
          bottom: layout.computedMargins.bottom,
          left: layout.computedMargins.left,
          right: layout.computedMargins.right,
          header: 0,
          footer: 0,
        }
      );

      // Skala
      applyScale(copiedSheet, page, layout);

      // Centering (hanya untuk posisi tengah)
      copiedSheet.pageLayout.centerHorizontally = page.position.horizontal === "center";
      copiedSheet.pageLayout.centerVertically = page.position.vertical === "center";

      // Opsi tambahan
      copiedSheet.pageLayout.printGridlines = page.gridlines;
      copiedSheet.pageLayout.printHeadings = page.headings;
      copiedSheet.pageLayout.blackAndWhite = page.blackAndWhite;

      // 6. Sembunyikan sheet staging
      copiedSheet.visibility = Excel.SheetVisibility.hidden;

      await context.sync();
    });

    return stagingName;
  } catch (err) {
    logger.logError(`createStagingSheet(halaman ${index + 1})`, err);
    throw err;
  }
}

/**
 * Terapkan pengaturan skala ke sheet.
 */
function applyScale(
  sheet: Excel.Worksheet,
  page: PageItem,
  _layout: LayoutCalculation
): void {
  switch (page.scaleMode) {
    case "fitWidth":
      sheet.pageLayout.zoom = {
        horizontalFitToPages: 1,
        verticalFitToPages: 0, // [SPIKE] perlu diuji: 0 vs null vs hilangkan
      } as any;
      break;

    case "fitPage":
      sheet.pageLayout.zoom = {
        horizontalFitToPages: 1,
        verticalFitToPages: 1,
      } as any;
      break;

    case "custom":
      sheet.pageLayout.zoom = {
        scale: page.customScale,
      } as any;
      break;

    case "actual":
      sheet.pageLayout.zoom = {
        scale: 100,
      } as any;
      break;
  }
}

/**
 * Buat semua staging sheet untuk seluruh antrean.
 * Mengembalikan daftar nama staging sheet yang berhasil dibuat.
 */
export async function createAllStagingSheets(
  pages: PageItem[],
  layouts: LayoutCalculation[],
  onProgress?: (current: number, total: number) => void
): Promise<string[]> {
  const stagingNames: string[] = [];

  for (let i = 0; i < pages.length; i++) {
    if (!pages[i].isValid) {
      throw new Error(
        `Halaman ${i + 1} ("${pages[i].sheetName}!${pages[i].address}") tidak valid. Perbaiki atau hapus sebelum ekspor.`
      );
    }

    const name = await createStagingSheet(pages[i], i, layouts[i]);
    stagingNames.push(name);
    onProgress?.(i + 1, pages.length);
  }

  return stagingNames;
}

/**
 * Sembunyikan semua sheet non-staging dan tampilkan semua staging sheet.
 * Diperlukan agar getFileAsync(Pdf) hanya mengekspor staging.
 * [SPIKE] Perlu diverifikasi apakah ini benar-benar diperlukan.
 *
 * @returns state visibilitas asli untuk dipulihkan nanti
 */
export async function prepareForExport(
  stagingNames: string[]
): Promise<Array<{ name: string; visibility: Excel.SheetVisibility | "Visible" | "Hidden" | "VeryHidden" }>> {
  return Excel.run(async (context) => {
    const sheets = context.workbook.worksheets;
    sheets.load("items/name, items/visibility");
    await context.sync();

    const originalStates = sheets.items.map((s) => ({
      name: s.name,
      visibility: s.visibility,
    }));

    // Tampilkan staging, sembunyikan yang lain
    for (const sheet of sheets.items) {
      if (stagingNames.includes(sheet.name)) {
        sheet.visibility = Excel.SheetVisibility.visible;
      } else {
        sheet.visibility = Excel.SheetVisibility.hidden;
      }
    }

    // Aktifkan staging pertama
    if (stagingNames.length > 0) {
      const first = context.workbook.worksheets.getItem(stagingNames[0]);
      first.activate();
    }

    await context.sync();
    return originalStates;
  });
}

/**
 * Pulihkan visibilitas sheet dan hapus semua staging sheet.
 * WAJIB dipanggil di blok `finally`.
 */
export type SheetVisibilityValue = Excel.SheetVisibility | "Visible" | "Hidden" | "VeryHidden";

export async function cleanupStaging(
  stagingNames: string[],
  originalStates: Array<{ name: string; visibility: SheetVisibilityValue }>
): Promise<void> {
  await Excel.run(async (context) => {
    const sheets = context.workbook.worksheets;

    // Pulihkan visibilitas asli terlebih dahulu
    // (harus ada minimal 1 sheet visible sebelum menghapus staging)
    for (const state of originalStates) {
      try {
        const sheet = sheets.getItemOrNullObject(state.name);
        sheet.load("isNullObject");
        await context.sync();

        if (!sheet.isNullObject) {
          sheet.visibility = state.visibility;
        }
      } catch {
        // Sheet mungkin sudah tidak ada
      }
    }
    await context.sync();

    // Hapus semua staging sheet
    for (const name of stagingNames) {
      try {
        const sheet = sheets.getItemOrNullObject(name);
        sheet.load("isNullObject");
        await context.sync();

        if (!sheet.isNullObject) {
          sheet.delete();
        }
      } catch {
        // Abaikan error saat cleanup
      }
    }
    await context.sync();
  });
}
