/**
 * persistenceService.ts — Menyimpan & memuat antrean halaman dari workbook
 *
 * Data disimpan di workbook settings (bukan customXmlParts) agar
 * ikut tersimpan bersama file .xlsx.
 * Ref: PRD §8 (Persistensi dan Data)
 */

import type { PageItem, PrintStudioData } from "@shared/types";
import { PERSISTENCE_KEY, DATA_VERSION } from "@shared/constants";

/**
 * Simpan antrean halaman ke dalam workbook settings.
 */
export async function saveQueue(pages: PageItem[]): Promise<void> {
  const data: PrintStudioData = {
    version: DATA_VERSION,
    pages,
  };

  await Excel.run(async (context) => {
    const settings = context.workbook.settings;
    settings.add(PERSISTENCE_KEY, JSON.stringify(data));
    await context.sync();
  });
}

/**
 * Muat antrean halaman dari workbook settings.
 * Mengembalikan array kosong jika tidak ada data tersimpan.
 */
export async function loadQueue(): Promise<PageItem[]> {
  try {
    return await Excel.run(async (context) => {
      const setting = context.workbook.settings.getItemOrNullObject(PERSISTENCE_KEY);
      setting.load("value");
      await context.sync();

      if (setting.isNullObject || !setting.value) {
        return [];
      }

      const raw = JSON.parse(setting.value) as PrintStudioData;

      // Migrasi skema jika versi berbeda
      if (raw.version !== DATA_VERSION) {
        return migrateData(raw);
      }

      return raw.pages;
    });
  } catch {
    return [];
  }
}

/**
 * Hapus data antrean dari workbook settings.
 */
export async function clearQueue(): Promise<void> {
  try {
    await Excel.run(async (context) => {
      const setting = context.workbook.settings.getItemOrNullObject(PERSISTENCE_KEY);
      setting.load("isNullObject");
      await context.sync();

      if (!setting.isNullObject) {
        setting.delete();
        await context.sync();
      }
    });
  } catch {
    // Abaikan error
  }
}

// ─── Migrasi data ─────────────────────────────────────────────────

/**
 * Migrasi data dari versi lama ke versi saat ini.
 * Untuk saat ini hanya ada versi 1, jadi ini placeholder.
 */
function migrateData(data: PrintStudioData): PageItem[] {
  // TODO: implementasi migrasi sesuai kebutuhan
  console.warn(`Migrasi data dari versi ${data.version} ke ${DATA_VERSION}`);
  return data.pages ?? [];
}
