import { useCallback, useRef } from "react";
import { useAppContext } from "@store/appState";
import { runExport, downloadPdf, openPdfInViewer } from "@services/pdfExportService";
import { openDialog, getAllRangesDimensions } from "@services/excelService";
import { logger } from "@services/loggerService";

export function useExportPdf() {
  const { state, dispatch } = useAppContext();
  const cancelledRef = useRef(false);

  /**
   * Eksekusi alur pembuatan PDF bersama
   */
  const executeExport = useCallback(
    async (onSuccess: (data: Uint8Array) => void) => {
      const { pages } = state;

      logger.addEntry("info", `[useExportPdf] Memulai ekspor untuk ${pages.length} halaman.`);

      if (pages.length === 0) {
        logger.addEntry("warn", "[useExportPdf] Ekspor dibatalkan: tidak ada halaman dalam antrean.");
        dispatch({
          type: "SET_STATUS",
          message: { type: "warning", text: "Tidak ada halaman untuk diekspor." },
        });
        return;
      }

      // Cek apakah ada halaman tidak valid
      const invalidPages = pages.filter((p) => !p.isValid);
      if (invalidPages.length > 0) {
        logger.addEntry(
          "error",
          `[useExportPdf] Terdapat ${invalidPages.length} halaman tidak valid: ${invalidPages.map((p) => `${p.sheetName}!${p.address}`).join(", ")}`
        );
        dispatch({
          type: "SET_STATUS",
          message: {
            type: "error",
            text: `${invalidPages.length} halaman tidak valid. Perbaiki atau hapus sebelum ekspor.`,
          },
        });
        return;
      }

      try {
        cancelledRef.current = false;
        dispatch({ type: "SET_EXPORTING", isExporting: true, progress: 0 });

        // Ambil dimensi riil konten dari Excel API (range.width/height)
        dispatch({
          type: "SET_STATUS",
          message: { type: "info", text: "Mengukur dimensi konten..." },
        });
        logger.addEntry("info", "[useExportPdf] Mengukur dimensi ranges...");
        const contentDimensions = await getAllRangesDimensions(pages);
        logger.addEntry(
          "info",
          `[useExportPdf] Dimensi diperoleh: ${JSON.stringify(contentDimensions)}`
        );

        const result = await runExport(pages, contentDimensions, {
          onProgress: (percent, message) => {
            dispatch({ type: "SET_EXPORT_PROGRESS", progress: percent });
            dispatch({
              type: "SET_STATUS",
              message: { type: "info", text: message },
            });
            logger.addEntry("info", `[Progres Ekspor ${Math.round(percent)}%] ${message}`);
          },
          isCancelled: () => cancelledRef.current,
        });

        dispatch({ type: "SET_EXPORTING", isExporting: false });

        if (result.cancelled) {
          logger.addEntry("info", "[useExportPdf] Proses ekspor dibatalkan oleh pengguna.");
          dispatch({
            type: "SET_STATUS",
            message: { type: "info", text: "Ekspor dibatalkan." },
          });
        } else if (result.success && result.pdfData) {
          logger.addEntry(
            "info",
            `[useExportPdf] Ekspor BERHASIL. Ukuran PDF: ${result.pdfData.byteLength} bytes.`
          );
          dispatch({
            type: "SET_STATUS",
            message: { type: "success", text: "PDF berhasil dibuat!" },
          });
          onSuccess(result.pdfData);
        } else {
          logger.addEntry(
            "error",
            `[useExportPdf GAGAL] ${result.error ?? "Tidak ada pesan error spesifik."}`
          );
          dispatch({
            type: "SET_STATUS",
            message: { type: "error", text: result.error ?? "Gagal mengekspor PDF." },
          });
        }
      } catch (err: unknown) {
        dispatch({ type: "SET_EXPORTING", isExporting: false });
        logger.logError("useExportPdf.executeExport", err);
        const errText = err instanceof Error ? err.message : String(err);
        dispatch({
          type: "SET_STATUS",
          message: { type: "error", text: `Error saat ekspor: ${errText}` },
        });
      }
    },
    [state, dispatch]
  );

  /** Ekspor dan unduh PDF */
  const startExport = useCallback(() => {
    return executeExport((data) => downloadPdf(data));
  }, [executeExport]);

  /** Ekspor dan buka PDF di jendela penampil untuk dicetak */
  const startPrint = useCallback(() => {
    return executeExport((data) => openPdfInViewer(data));
  }, [executeExport]);

  /** Buka dialog pratinjau penuh */
  const openFullPreview = useCallback(async () => {
    const dialogUrl = `${window.location.origin}/dialog.html`;
    try {
      await openDialog(dialogUrl, 80, 80);
    } catch (err) {
      console.warn("Gagal membuka dialog pratinjau:", err);
      dispatch({
        type: "SET_STATUS",
        message: { type: "error", text: "Tidak dapat membuka jendela pratinjau." },
      });
    }
  }, [dispatch]);

  const cancelExport = useCallback(() => {
    cancelledRef.current = true;
  }, []);

  return {
    isExporting: state.isExporting,
    exportProgress: state.exportProgress,
    startExport,
    startPrint,
    openFullPreview,
    cancelExport,
  };
}
