/**
 * usePageQueue.ts — Hook untuk mengelola antrean halaman
 */

import { useCallback } from "react";
import { v4 as uuidv4 } from "uuid";
import { useAppContext } from "@store/appState";
import type { PageItem } from "@shared/types";
import { DEFAULT_MARGINS, DEFAULT_POSITION, MAX_QUEUE_PAGES } from "@shared/constants";
import { DEFAULT_PAPER } from "@shared/paperSizes";
import { getSelectedRange } from "@services/excelService";
import { saveQueue } from "@services/persistenceService";

export function usePageQueue() {
  const { state, dispatch } = useAppContext();
  const { pages, selectedPageIndex } = state;

  /** Halaman yang sedang dipilih */
  const selectedPage = selectedPageIndex !== null ? pages[selectedPageIndex] : null;

  /**
   * Tambah seleksi aktif sebagai halaman baru.
   */
  const addFromSelection = useCallback(async () => {
    if (pages.length >= MAX_QUEUE_PAGES) {
      dispatch({
        type: "SET_STATUS",
        message: { type: "warning", text: `Maksimum ${MAX_QUEUE_PAGES} halaman tercapai.` },
      });
      return;
    }

    const selection = await getSelectedRange();
    if (!selection) {
      dispatch({
        type: "SET_STATUS",
        message: { type: "warning", text: "Tidak ada seleksi aktif." },
      });
      return;
    }

    if (selection.isReadOnly) {
      dispatch({
        type: "SET_STATUS",
        message: {
          type: "warning",
          text: "Workbook dalam mode baca-saja. Ekspor tidak tersedia.",
        },
      });
      return;
    }

    const page: PageItem = {
      id: uuidv4(),
      sheetId: selection.sheetId,
      sheetName: selection.sheetName,
      address: selection.address,
      paper: DEFAULT_PAPER,
      orientation: "portrait",
      autoRotate: true,
      margins: { ...DEFAULT_MARGINS },
      position: { ...DEFAULT_POSITION },
      scaleMode: "fitWidth",
      customScale: 100,
      gridlines: false,
      headings: false,
      blackAndWhite: false,
      isValid: true,
    };

    dispatch({ type: "ADD_PAGE", page });

    // Tampilkan peringatan jika mendeteksi kasus khusus (edge case)
    let warningNote = "";
    if (selection.isProtected) {
      warningNote = " (Sheet dilindungi — salinan mungkin dibatasi)";
    } else if (selection.isTooLarge) {
      warningNote = " (Peringatan: range > 100.000 sel)";
    } else if (selection.hasMergedCells) {
      warningNote = " (Mengandung sel gabungan)";
    } else if (selection.hasHiddenCells) {
      warningNote = " (Baris/kolom tersembunyi tidak akan tercetak)";
    }

    dispatch({
      type: "SET_STATUS",
      message: {
        type: warningNote ? "warning" : "success",
        text: `Ditambahkan: ${selection.sheetName}!${selection.address}${warningNote}`,
      },
    });

    // Auto-save
    await saveQueue([...pages, page]);
  }, [pages, dispatch]);

  /** Hapus halaman */
  const removePage = useCallback(
    async (index: number) => {
      dispatch({ type: "REMOVE_PAGE", index });
      const newPages = pages.filter((_, i) => i !== index);
      await saveQueue(newPages);
    },
    [pages, dispatch]
  );

  /** Duplikat halaman */
  const duplicatePage = useCallback(
    async (index: number) => {
      if (pages.length >= MAX_QUEUE_PAGES) return;
      dispatch({ type: "DUPLICATE_PAGE", index });
      // Save setelah state update (ideally via useEffect)
    },
    [pages, dispatch]
  );

  /** Pindahkan halaman naik */
  const moveUp = useCallback(
    async (index: number) => {
      if (index <= 0) return;
      dispatch({ type: "MOVE_PAGE", from: index, to: index - 1 });
    },
    [dispatch]
  );

  /** Pindahkan halaman turun */
  const moveDown = useCallback(
    async (index: number) => {
      if (index >= pages.length - 1) return;
      dispatch({ type: "MOVE_PAGE", from: index, to: index + 1 });
    },
    [pages.length, dispatch]
  );

  /** Pilih halaman */
  const selectPage = useCallback(
    (index: number | null) => {
      dispatch({ type: "SELECT_PAGE", index });
    },
    [dispatch]
  );

  /** Daftar kunci properti layout yang disinkronkan */
  const LAYOUT_KEYS: (keyof PageItem)[] = [
    "paper",
    "orientation",
    "autoRotate",
    "margins",
    "position",
    "scaleMode",
    "customScale",
    "gridlines",
    "headings",
    "blackAndWhite",
  ];

  /** Terapkan tata letak halaman tertentu ke semua halaman */
  const applyToAllPages = useCallback(
    async (sourceIndex: number) => {
      const source = pages[sourceIndex];
      if (!source) return;

      const newPages = pages.map((p) => ({
        ...p,
        paper: source.paper,
        orientation: source.orientation,
        autoRotate: source.autoRotate,
        margins: { ...source.margins },
        position: { ...source.position },
        scaleMode: source.scaleMode,
        customScale: source.customScale,
        gridlines: source.gridlines,
        headings: source.headings,
        blackAndWhite: source.blackAndWhite,
      }));

      dispatch({ type: "SET_PAGES", pages: newPages });
      await saveQueue(newPages);
    },
    [pages, dispatch]
  );

  /** Aktifkan / nonaktifkan mode terapkan ke semua */
  const setApplyToAll = useCallback(
    async (enabled: boolean) => {
      dispatch({ type: "SET_APPLY_TO_ALL", applyToAll: enabled });
      if (enabled && selectedPageIndex !== null) {
        await applyToAllPages(selectedPageIndex);
      }
    },
    [dispatch, selectedPageIndex, applyToAllPages]
  );

  /** Update halaman tertentu (atau semua jika applyToAll aktif) */
  const updatePage = useCallback(
    async (index: number, updates: Partial<PageItem>) => {
      const current = pages[index];
      if (!current) return;

      if (state.applyToAll) {
        const layoutUpdates: Partial<PageItem> = {};
        for (const key of LAYOUT_KEYS) {
          if (key in updates) {
            (layoutUpdates as any)[key] = updates[key];
          }
        }

        const newPages = pages.map((p, i) =>
          i === index ? { ...p, ...updates } : { ...p, ...layoutUpdates }
        );
        dispatch({ type: "SET_PAGES", pages: newPages });
        await saveQueue(newPages);
      } else {
        const updated: PageItem = { ...current, ...updates };
        dispatch({ type: "UPDATE_PAGE", index, page: updated });

        const newPages = [...pages];
        newPages[index] = updated;
        await saveQueue(newPages);
      }
    },
    [pages, state.applyToAll, dispatch]
  );

  return {
    pages,
    selectedPage,
    selectedPageIndex,
    applyToAll: state.applyToAll,
    setApplyToAll,
    applyToAllPages,
    addFromSelection,
    removePage,
    duplicatePage,
    moveUp,
    moveDown,
    selectPage,
    updatePage,
  };
}
