/**
 * LayoutTabs.tsx — Kontainer tab pengaturan layout per halaman
 *
 * Tab: Kertas | Margin | Posisi | Skala | Lain
 * Ref: PRD §5
 */

import React from "react";
import {
  Tab,
  TabList,
  Checkbox,
} from "@fluentui/react-components";
import { useAppContext } from "@store/appState";
import { usePageQueue } from "@hooks/usePageQueue";
import { getTranslations } from "@shared/i18n";
import type { LayoutTab } from "@shared/types";
import { PaperTab } from "./PaperTab";
import { MarginTab } from "./MarginTab";
import { PositionGrid } from "./PositionGrid";
import { ScaleTab } from "./ScaleTab";
import { MiscTab } from "./MiscTab";
import "./LayoutTabs.css";

export const LayoutTabs: React.FC = () => {
  const { state, dispatch } = useAppContext();
  const { applyToAll, setApplyToAll, pages } = usePageQueue();
  const t = getTranslations(state.locale);

  const handleTabSelect = (_: unknown, data: { value: unknown }) => {
    dispatch({ type: "SET_LAYOUT_TAB", tab: data.value as LayoutTab });
  };

  const renderTabContent = () => {
    switch (state.activeLayoutTab) {
      case "paper":
        return <PaperTab />;
      case "margin":
        return <MarginTab />;
      case "position":
        return <PositionGrid />;
      case "scale":
        return <ScaleTab />;
      case "misc":
        return <MiscTab />;
      default:
        return null;
    }
  };

  return (
    <div className="layout-tabs">
      <TabList
        selectedValue={state.activeLayoutTab}
        onTabSelect={handleTabSelect}
        size="small"
      >
        <Tab value="paper">{t.tabPaper}</Tab>
        <Tab value="margin">{t.tabMargin}</Tab>
        <Tab value="position">{t.tabPosition}</Tab>
        <Tab value="scale">{t.tabScale}</Tab>
        <Tab value="misc">{t.tabMisc}</Tab>
      </TabList>

      <div className="layout-tabs__content">
        {renderTabContent()}
      </div>

      {/* Terapkan ke semua halaman */}
      <div className="layout-tabs__apply-all">
        <Checkbox
          label={t.applyToAll}
          size="medium"
          checked={applyToAll}
          onChange={(_, data) => setApplyToAll(Boolean(data.checked))}
          disabled={pages.length <= 1}
        />
      </div>
    </div>
  );
};
