/**
 * QuickPreview.tsx — Pratinjau cepat (wireframe/schematic)
 *
 * Menampilkan representasi skematis: kertas, garis margin, kotak konten, posisi.
 * Label "Perkiraan" ditampilkan jelas.
 * Ref: PRD §4 Fitur 3
 */

import React, { useMemo } from "react";
import { Text } from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { PAPER_SIZES } from "@shared/paperSizes";
import { formatPercent } from "@shared/utils";
import "./QuickPreview.css";

/** Lebar maksimal preview area dalam px */
const PREVIEW_MAX_WIDTH = 260;

export const QuickPreview: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage } = usePageQueue();

  // Hitung dimensi preview
  const previewData = useMemo(() => {
    if (!selectedPage) return null;

    const paper = PAPER_SIZES[selectedPage.paper];
    if (!paper) return null;

    const isLandscape = selectedPage.orientation === "landscape";
    const paperW = isLandscape ? paper.heightMm : paper.widthMm;
    const paperH = isLandscape ? paper.widthMm : paper.heightMm;

    // Skala ke ukuran preview
    const scale = PREVIEW_MAX_WIDTH / paperW;
    const displayW = paperW * scale;
    const displayH = paperH * scale;

    // Margin sebagai persentase
    const marginTop = (selectedPage.margins.top / paperH) * 100;
    const marginBottom = (selectedPage.margins.bottom / paperH) * 100;
    const marginLeft = (selectedPage.margins.left / paperW) * 100;
    const marginRight = (selectedPage.margins.right / paperW) * 100;

    // Konten area (sederhanakan: asumsikan konten mengisi area cetak)
    const contentLeft = marginLeft;
    const contentTop = marginTop;
    const contentWidth = 100 - marginLeft - marginRight;
    const contentHeight = 100 - marginTop - marginBottom;

    // Posisikan konten dalam printable area berdasarkan 9-titik
    // (Sederhanakan: konten lebih kecil dari area cetak)
    const contentScale = 0.6; // placeholder — nanti dari layout engine
    const actualContentW = contentWidth * contentScale;
    const actualContentH = contentHeight * contentScale;

    let cx = contentLeft;
    let cy = contentTop;

    switch (selectedPage.position.horizontal) {
      case "left": cx = contentLeft; break;
      case "center": cx = contentLeft + (contentWidth - actualContentW) / 2; break;
      case "right": cx = contentLeft + contentWidth - actualContentW; break;
    }

    switch (selectedPage.position.vertical) {
      case "top": cy = contentTop; break;
      case "center": cy = contentTop + (contentHeight - actualContentH) / 2; break;
      case "bottom": cy = contentTop + contentHeight - actualContentH; break;
    }

    return {
      displayW,
      displayH,
      marginTop,
      marginBottom,
      marginLeft,
      marginRight,
      contentX: cx,
      contentY: cy,
      contentW: actualContentW,
      contentH: actualContentH,
    };
  }, [selectedPage]);

  if (!selectedPage || !previewData) {
    return (
      <div className="quick-preview-empty">
        <Text size={200}>{t.quickPreviewNote}</Text>
      </div>
    );
  }

  return (
    <div className="quick-preview">
      <div className="quick-preview__header">
        <Text size={200} weight="semibold">{t.quickPreview}</Text>
        <Text size={100} className="quick-preview__badge">{t.quickPreviewNote}</Text>
      </div>

      <div className="quick-preview__canvas-wrapper">
        <svg
          className="quick-preview__canvas"
          width={previewData.displayW}
          height={previewData.displayH}
          viewBox={`0 0 100 ${(previewData.displayH / previewData.displayW) * 100}`}
          aria-label="Pratinjau tata letak halaman"
        >
          {/* Kertas */}
          <rect
            x="0" y="0"
            width="100"
            height={(previewData.displayH / previewData.displayW) * 100}
            fill="white"
            stroke="#ccc"
            strokeWidth="0.5"
          />

          {/* Garis margin (putus-putus) */}
          <rect
            x={previewData.marginLeft}
            y={previewData.marginTop}
            width={100 - previewData.marginLeft - previewData.marginRight}
            height={(previewData.displayH / previewData.displayW) * 100 - previewData.marginTop - previewData.marginBottom}
            fill="none"
            stroke="#aaddff"
            strokeWidth="0.3"
            strokeDasharray="2 1"
          />

          {/* Kotak konten */}
          <rect
            x={previewData.contentX}
            y={previewData.contentY}
            width={previewData.contentW}
            height={previewData.contentH}
            fill="#e8f0fe"
            stroke="#4285f4"
            strokeWidth="0.5"
            rx="0.5"
          />

          {/* Label "KONTEN" */}
          <text
            x={previewData.contentX + previewData.contentW / 2}
            y={previewData.contentY + previewData.contentH / 2}
            textAnchor="middle"
            dominantBaseline="middle"
            fontSize="3"
            fill="#4285f4"
          >
            KONTEN
          </text>
        </svg>
      </div>

      {/* Info footer */}
      <div className="quick-preview__info">
        <Text size={100}>
          {t.effectiveScale}: {formatPercent(selectedPage.customScale)}
        </Text>
      </div>
    </div>
  );
};
